/** Static assets owned by the views package: the compiled theme CSS plus the
 * verbatim `public/**` port (fonts, JS, icons). Upstream: nitter
 * `src/sass/**` + `public/**` @ 145ca9e (master HEAD, Oct 2026), AGPL-3.0.
 * One deliberate divergence: `sass/include/_mixins.css` is `_mixins.scss`
 * here — its content is SCSS, which libsass tolerated under `.css` but
 * dart-sass parses as plain CSS (see `scripts/build-css.mjs`).
 *
 * `public/css/style.css` is generated by `scripts/build-css.mjs` (the
 * `tools/gencss.nim` port) and gitignored like upstream; everything else
 * under `public/` is checked in verbatim. */
import { existsSync, readdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { titleize } from "./formatters.ts";

/** Absolute path to the directory `ctx.server.static("/", dir)` should serve.
 *
 * Prefers the staged copy (`dist/public/`, present after `pnpm build`) and
 * falls back to the source tree (`public/`, used by vitest). Keyed on a
 * checked-in file so a build without the staging step still resolves. */
export function viewsPublicDir(): string {
  const here = dirname(fileURLToPath(import.meta.url));
  for (const candidate of [resolve(here, "public"), resolve(here, "../public")]) {
    if (existsSync(resolve(candidate, "css/fontello.css"))) return candidate;
  }
  return resolve(here, "../public");
}

/**
 * Port of nitter's `findThemes` (`routes/preferences.nim`): the `<name>` of
 * every `css/themes/*.css` file under `dir`, with `_` turned into a space and
 * each word titleized (`twitter_dark` -> "Twitter Dark"), sorted. The settings
 * page feeds this to the theme `<select>`; an unreadable directory yields no
 * themes rather than throwing.
 */
export function findThemes(dir: string): string[] {
  try {
    return readdirSync(join(dir, "css", "themes"))
      .filter((file) => file.endsWith(".css"))
      .map((file) => titleize(file.slice(0, -".css".length).replaceAll("_", " ")))
      .sort();
  } catch {
    return [];
  }
}
